-- «balón» → «pelota» en los textos de «cómo se hace» (pedido de Manu, 2026-11-27).
update public.exercises set instructions = 'Arrodillado, lanzá la pelota desde el pecho hacia adelante o contra la pared con máxima fuerza.', coaching_cues = 'Glúteos apretados. Torso firme. Solo empujan los brazos.' where org_id is null and name = 'Pase de pecho arrodillado';
update public.exercises set instructions = 'De frente a la pared a 1–2 metros, lanzá la pelota desde el pecho con fuerza y atrapala al rebote.', coaching_cues = 'Codos detrás de la pelota. Extensión rápida de brazos. Ritmo alto.' where org_id is null and name = 'Pase de pecho contra la pared';
update public.exercises set instructions = 'De costado a un compañero a 3–4 metros, recibí la pelota, cargá atrás y devolvela rotando con máxima velocidad.', coaching_cues = 'Recibir y lanzar en un solo movimiento. Cadera inicia.' where org_id is null and name = 'Pase rotacional con compañero';
update public.exercises set instructions = 'En un espacio abierto, de costado a la dirección de lanzamiento, lanzá la pelota lo más lejos posible rotando. Podés medir la distancia.', coaching_cues = 'Máxima intención. Descanso completo entre lanzamientos.' where org_id is null and name = 'Lanzamiento rotacional a distancia';
update public.exercises set instructions = 'Arrodillado, elevá la pelota y golpeala contra el piso adelante.', coaching_cues = 'Sin arquear la espalda. Fuerza desde el tronco.' where org_id is null and name = 'Slam de pelota medicinal arrodillado';
update public.exercises set instructions = 'En postura de address, juntá los pies, dá un paso hacia el objetivo con el pie de adelante (como en el swing) y lanzá la pelota contra la pared.', coaching_cues = 'Paso antes de lanzar. La cadera abre primero. Mantené la inclinación del torso.' where org_id is null and name = 'Lanzamiento rotacional en posición de golf con paso';
update public.exercises set instructions = 'Con la pelota entre las piernas, hacé una bisagra de cadera y lanzala hacia adelante y arriba extendiendo la cadera con fuerza.', coaching_cues = 'Espalda neutra. La cadera empuja. Brazos largos.' where org_id is null and name = 'Lanzamiento desde abajo entre las piernas';
update public.exercises set instructions = 'De frente a la pared, a 1 metro, llevá la pelota hacia la cadera de atrás y lanzala rotando el cuerpo hasta quedar mirando la pared.', coaching_cues = 'Empieza la cadera. Pie de atrás pivotea. Máxima velocidad en cada lanzamiento.' where org_id is null and name = 'Lanzamiento rotacional frontal a la pared';
update public.exercises set instructions = 'Desde el pecho, lanzá la pelota hacia adelante explosivamente extendiendo brazos y piernas.', coaching_cues = 'Triple extensión. Máxima velocidad. Pocas repeticiones.' where org_id is null and name = 'Pase de pecho con pelota medicinal';
update public.exercises set instructions = 'Acostado con rodillas flexionadas frente a la pared o un compañero, subí haciendo un abdominal y lanzá la pelota desde el pecho o por encima de la cabeza.', coaching_cues = 'Subí con el abdomen. Lanzamiento al final de la subida. Bajada controlada.' where org_id is null and name = 'Abdominal con lanzamiento de pelota';
update public.exercises set instructions = 'De costado a la pared, llevá la pelota por encima del hombro de atrás y lanzala en diagonal hacia abajo contra la pared o el piso.', coaching_cues = 'Rotá y bajá a la vez. Pies firmes. Atrapá controlado.' where org_id is null and name = 'Lanzamiento rotacional alto en diagonal';
update public.exercises set instructions = 'De frente a la pared, llevá la pelota detrás de la cabeza y lanzala con fuerza como un saque de lateral.', coaching_cues = 'Costillas abajo. Lanzamiento con todo el cuerpo. Atrapá y repetí.' where org_id is null and name = 'Lanzamiento por encima de la cabeza contra la pared';
update public.exercises set instructions = 'Elevá la pelota sobre la cabeza y lanzala con fuerza contra el piso.', coaching_cues = 'Extenderse arriba. Golpear con todo el cuerpo. Atrapar y repetir.' where org_id is null and name = 'Slam de pelota medicinal';
update public.exercises set instructions = 'De costado a la pared, cargá en la pierna de atrás y lanzá la pelota rotando desde la cadera con máxima velocidad.', coaching_cues = 'La cadera inicia. Brazos acompañan. Máxima intención en cada lanzamiento.' where org_id is null and name = 'Lanzamiento rotacional de pelota medicinal';
update public.exercises set instructions = 'En postura de address, hacé un backswing corto y lanzá la pelota contra la pared imitando la secuencia del swing.', coaching_cues = 'Secuencia cadera-tronco-brazos. Pies firmes. Recuperar entre repeticiones.' where org_id is null and name = 'Lanzamiento rotacional en posición de golf';
update public.exercises set instructions = 'Con la pelota arriba, rotá y lanzala con fuerza contra el piso por fuera de un pie. Alterná o hacé todas de un lado.', coaching_cues = 'Pivoteá el pie de atrás. Golpe con todo el cuerpo. Pelota que no rebote.' where org_id is null and name = 'Slam rotacional de pelota medicinal';
update public.exercises set instructions = 'Sentado en el piso o en un cajón, de costado a la pared, rotá el torso y lanzá la pelota.', coaching_cues = 'Espalda larga. Solo rota el tronco. Velocidad máxima.' where org_id is null and name = 'Lanzamiento rotacional sentado';
update public.exercises set instructions = 'Un compañero te lanza la pelota de costado: recibila y frená la rotación hacia atrás, quedando estable 2 segundos antes de devolverlo.', coaching_cues = 'Frená con la cadera y el tronco. Pies firmes. Sin perder la postura.' where org_id is null and name = 'Desaceleración rotacional con pelota';
update public.exercises set instructions = 'Parado sobre la pierna de atrás, de costado a la pared, rotá y lanzá la pelota manteniendo el equilibrio.', coaching_cues = 'Rodilla apenas flexionada. Cadera estable. Lanzá sin perder el equilibrio.' where org_id is null and name = 'Lanzamiento rotacional en una pierna';
update public.exercises set instructions = 'Con la pelota en el pecho, bajá a media sentadilla y lanzala hacia adelante y arriba mientras saltás.', coaching_cues = 'Triple extensión. Pelota y cuerpo salen juntos. Caída suave.' where org_id is null and name = 'Lanzamiento de pecho con salto';
update public.exercises set instructions = 'Con la pelota detrás de la cabeza, dá un paso adelante y lanzala lo más lejos posible.', coaching_cues = 'Paso y lanzamiento encadenados. Extensión completa.' where org_id is null and name = 'Lanzamiento por encima de la cabeza con paso';
update public.exercises set instructions = 'Sentado con el tronco inclinado y pies elevados o apoyados, lanzá la pelota a un compañero o a la pared rotando de un lado al otro.', coaching_cues = 'Rotar el tronco. Core firme. Ritmo constante.' where org_id is null and name = 'Russian twist con lanzamiento';
update public.exercises set instructions = 'Parado en una pierna, elevá la pelota y golpeala contra el piso manteniendo el equilibrio.', coaching_cues = 'Equilibrio primero. Core firme. Golpe fuerte.' where org_id is null and name = 'Slam de pelota medicinal unipodal';
update public.exercises set instructions = 'De costado a la pared, llevá la pelota por fuera de la rodilla de atrás y lanzá en diagonal hacia arriba, como un golpe de hacha invertido.', coaching_cues = 'Bajá con la cadera, no con la espalda. Diagonal de abajo hacia arriba.' where org_id is null and name = 'Lanzamiento rotacional bajo';
update public.exercises set instructions = 'Sentado con el tronco inclinado, rotá llevando la pelota de lado a lado.', coaching_cues = 'Rotar el tronco, no solo los brazos. Espalda larga.' where org_id is null and name = 'Russian twist con pelota';
update public.exercises set instructions = 'Con la pelota entre las piernas, extendé cadera y lanzala hacia atrás por encima de la cabeza.', coaching_cues = 'Bisagra de cadera. Extensión explosiva. Espacio libre detrás.' where org_id is null and name = 'Lanzamiento hacia atrás por encima de la cabeza';
update public.exercises set instructions = 'Con la pelota en el pecho, hacé un salto lateral alejándote de la pared, caé en la pierna de atrás y lanzá rotando apenas apoyás.', coaching_cues = 'Caída estable. Cargá en la cadera de atrás. Lanzamiento inmediato.' where org_id is null and name = 'Lanzamiento rotacional tras salto lateral';
update public.exercises set instructions = 'Desde media sentadilla de costado a la pared, extendé las piernas y rotá para lanzar la pelota en diagonal hacia arriba.', coaching_cues = 'Piernas y rotación al mismo tiempo. Pies firmes.' where org_id is null and name = 'Lanzamiento lateral desde cuclillas';
update public.exercises set instructions = 'Sentado de costado a la pared, recibí la pelota, rotá hacia atrás y lanzala rotando hacia la pared.', coaching_cues = 'Espalda larga. Rotación rápida. Pies apoyados.' where org_id is null and name = 'Abdominal rotacional con lanzamiento';
update public.exercises set instructions = 'Desde media sentadilla con la pelota abajo, extendé todo el cuerpo y lanzala lo más alto posible. Dejala caer, no la atrapes.', coaching_cues = 'Triple extensión. Espacio libre arriba. Alejate al caer.' where org_id is null and name = 'Lanzamiento vertical hacia arriba';
update public.exercises set instructions = 'En posición de estocada o de pie, empujá la pelota con un brazo desde el pecho contra la pared, sumando rotación del torso.', coaching_cues = 'Empuja la cadera y el tronco, después el brazo. Pelota liviana.' where org_id is null and name = 'Pase de pecho a un brazo';
update public.exercises set instructions = 'Arrodillado frente a la pared, llevá la pelota detrás de la cabeza y lanzala con fuerza.', coaching_cues = 'No arquees la espalda. Glúteos firmes. Brazos rápidos.' where org_id is null and name = 'Lanzamiento por encima de la cabeza arrodillado';
update public.exercises set instructions = 'Arrodillado con las dos rodillas en el piso y de costado a la pared, rotá el torso y lanzá la pelota sin mover la cadera.', coaching_cues = 'Glúteos apretados. Rotación desde el tronco. Atrapá y repetí.' where org_id is null and name = 'Lanzamiento rotacional arrodillado';
update public.exercises set instructions = 'Arrodillado sobre colchoneta, lanzá la pelota hacia adelante y dejate caer controlado a posición de flexión, amortiguando con las manos.', coaching_cues = 'Cuerpo recto al caer. Codos suaves. Lanzá antes de caer.' where org_id is null and name = 'Pase de pecho con caída a flexión';
update public.exercises set instructions = 'De costado a la pared a 1 metro, lanzá y atrapá la pelota seguido, sin pausa, lo más rápido posible durante el tiempo indicado.', coaching_cues = 'Contacto corto. Cadera activa. Ritmo máximo sin perder la técnica.' where org_id is null and name = 'Lanzamiento rotacional reactivo';
update public.exercises set instructions = 'De costado a la pared, hacé un giro rápido hacia atrás (carga) y sin pausa lanzá la pelota rotando hacia la pared.', coaching_cues = 'Carga rápida y cambio de dirección sin frenar. Aprovechá el estiramiento.' where org_id is null and name = 'Lanzamiento rotacional con contramovimiento';
update public.exercises set instructions = 'Con una rodilla en el piso y la otra adelante, de costado a la pared, rotá y lanzá la pelota con fuerza.', coaching_cues = 'Torso erguido. Cadera estable. Rotación rápida.' where org_id is null and name = 'Lanzamiento rotacional en media rodilla';
